"""The person-steps inventory (docs/workflows/person-steps-inventory.md) is generated by scripts/gen_person_steps.py: the committed
file must equal the script's output, list every person step of every general definition, and the new general docs must name no
fact of the profile (docs/workflows/person-steps.md, the screen spec, and the design brief)."""

from __future__ import annotations

import importlib.util
import re
from pathlib import Path

import pytest

from jason.community import community
from jason.community.boundary import instance_terms, repo_root, scan

ROOT = repo_root()
SCRIPT = ROOT / "scripts" / "gen_person_steps.py"
INVENTORY = ROOT / "docs" / "workflows" / "person-steps-inventory.md"
PAGES = (
    "docs/workflows/person-steps.md",
    "docs/workflows/person-steps-inventory.md",
    "docs/console/screens/work-guide.md",
    "docs/console/design-brief-person-steps.md",
)
STALE = "run `.venv/Scripts/python scripts/gen_person_steps.py` and commit docs/workflows/person-steps-inventory.md"


@pytest.fixture(scope="module")
def gen():
    spec = importlib.util.spec_from_file_location("gen_person_steps", SCRIPT)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def test_the_inventory_equals_the_scripts_output(gen):
    assert INVENTORY.read_text(encoding="utf-8") == gen.render(), f"the inventory is stale: {STALE}"


def test_the_output_is_deterministic(gen):
    assert gen.render() == gen.render()


def test_every_person_step_of_every_definition_is_listed_once_and_no_other(gen):
    from jason.workflows.definitions_general import GENERAL
    from jason.workflows.defs import all_builders
    from jason.workflows.types import StepKind

    built = [b() for b in (*GENERAL, *all_builders())]
    expected = {s.id for w in built for s in w.steps if s.kind in (StepKind.PERSON, StepKind.DECISION)}
    others = {s.id for w in built for s in w.steps if s.kind not in (StepKind.PERSON, StepKind.DECISION)}
    listed = re.findall(r"^\| `([^`]+)`\*? \|", INVENTORY.read_text(encoding="utf-8"), flags=re.M)
    assert len(listed) == len(set(listed)), "a step is listed twice"
    assert set(listed) == expected, f"the inventory differs from the definitions: {STALE}"
    assert not set(listed) & others, "a check, job, plan, wait, or branch step is listed"
    assert len(built) == len({w.key for w in built}), "two definitions share a key"


def test_every_definition_has_a_heading_and_its_count(gen):
    text = INVENTORY.read_text(encoding="utf-8")
    for d in gen.collect():
        assert f"### `{d['key']}`" in text, d["key"]
        assert f"{len(d['rows'])} person steps of {d['steps']}." in text, d["key"]


def test_the_missing_codes_are_all_explained(gen):
    text = INVENTORY.read_text(encoding="utf-8")
    for code in gen.MISSING:
        assert f"- `{code}`:" in text
    used = {c for row in re.findall(r"^\| `[^`]+`\*? \|(.*)$", text, flags=re.M) for c in re.split(r", ", row.split("|")[-3].strip())}
    assert used - set(gen.MISSING) - {"-"} == set()


def test_the_inventory_names_only_person_and_decision_kinds():
    text = INVENTORY.read_text(encoding="utf-8")
    kinds = {cells[3].strip() for cells in (line.split("|") for line in text.splitlines() if re.match(r"^\| `[^`]+`\*? \|", line))}
    assert kinds == {"person", "decision"}


def test_a_held_or_admin_definition_is_marked():
    text = INVENTORY.read_text(encoding="utf-8")
    assert re.search(r"^### `hearing` \(held\)", text, flags=re.M)
    assert re.search(r"^### `check-in` \(administrator\)", text, flags=re.M)


def test_the_inventory_points_at_a_section_the_page_has():
    page = (ROOT / "docs" / "workflows" / "person-steps.md").read_text(encoding="utf-8")
    assert re.search(r"^## 10\. The human edges", page, flags=re.M)
    assert "section 10 of the page" in INVENTORY.read_text(encoding="utf-8")


def test_the_new_pages_are_indexed():
    for index, needle in (("docs/README.md", "workflows/person-steps.md"), ("docs/workflows/README.md", "person-steps.md"),
                          ("docs/console/design-index.md", "design-brief-person-steps.md")):
        assert needle in (ROOT / index).read_text(encoding="utf-8"), f"{index} does not link {needle}"
    assert "work-guide.md" in (ROOT / "docs/console/design-index.md").read_text(encoding="utf-8")


def test_the_new_pages_name_no_instance_facts():
    """The general docs name the association's facts nowhere (test_profile holds all of them to the baseline); these four are
    held to none, whatever the baseline says."""
    found = scan(ROOT, instance_terms(community()))
    mine = {path: terms for path, terms in found.items() if path in PAGES}
    assert not mine, f"instance facts in the person-steps pages: {mine}"


def test_the_new_pages_use_only_made_up_facts():
    """Samples are plainly fake: no 20xx date in 2026 or before in the design pages' samples, and the made-up names only."""
    for path in PAGES[2:]:
        text = (ROOT / path).read_text(encoding="utf-8")
        assert "Oakview" in text or "Example" in text or "A. Manager" in text, path
        for real in re.findall(r"\b20(?:2[0-9])-\d{2}-\d{2}\b", text):
            assert real.startswith("2099") or real == "2026-10-11", f"{path}: {real} is not a made-up 2099 date"


def test_the_spec_says_jason_sends_nothing_on_its_own():
    page = (ROOT / "docs" / "workflows" / "person-steps.md").read_text(encoding="utf-8")
    assert "jason sends nothing on its own" in page
    assert "a person sends it from Gmail" in page or "sent by a person" in page
    brief = (ROOT / "docs" / "console" / "design-brief-person-steps.md").read_text(encoding="utf-8")
    assert "Nothing is sent" in brief
